{%- set v_extras = ui_def(p['extras'], none) -%}
{%- set v_level = ui_def(p['level'], 1) -%}
{%- set v_layout = ui_def(p['layout'], 'split') -%}
{%- set v_mediaSide = ui_def(p['mediaSide'], 'end') -%}
