    {{ ui_include('blocks/post-author.html.j2', {'p': {'post': v_post, 'extras': v_extras, 'labels': v_labels, 'mode': 'card', 'share': true, 'className': ui_cnv(['mx-auto w-full max-w-md'])}}) }}
