    {{ ui_include('blocks/media-frame.html.j2', {'p': {'alt': ui_get(v_post, ['title']), 'ratio': ('21/9' if ui_t(ui_eq(v_layout, 'center')) else ('1/1' if ui_t(ui_eq(v_cover, 'square')) else '4/3'))}}) }}
